// --- Timestamp helpers ---

func tsToTimePtr(ts *timestamppb.Timestamp) *time.Time {
	if ts == nil {
		return nil
	}
	t := ts.AsTime()
	return &t
}

func timePtrToTs(t *time.Time) *timestamppb.Timestamp {
	if t == nil {
		return nil
	}
	return timestamppb.New(*t)
}

func timeToTs(t time.Time) *timestamppb.Timestamp {
	return timestamppb.New(t)
}

// --- Record conversion ---

func recordToProto(r *models.TraceabilityRecord) *pb.TraceabilityRecord {
	if r == nil {
		return nil
	}
	proto := &pb.TraceabilityRecord{
		Id:               r.ID,
		TenantId:         r.TenantID,
		FarmId:           r.FarmID,
		FieldId:          r.FieldID,
		CropId:           r.CropID,
		BatchNumber:      r.BatchNumber,
		ProductType:      r.ProductType,
		OriginCountry:    r.OriginCountry,
		OriginRegion:     r.OriginRegion,
		SeedSource:       r.SeedSource,
		PlantingDate:     timePtrToTs(r.PlantingDate),
		HarvestDate:      timePtrToTs(r.HarvestDate),
		ProcessingDate:   timePtrToTs(r.ProcessingDate),
		PackagingDate:    timePtrToTs(r.PackagingDate),
		QrCodeData:       r.QRCodeData,
		BlockchainHash:   r.BlockchainHash,
		ChainOfCustody:   r.ChainOfCustody,
		ComplianceStatus: complianceStatusModelToProto(r.ComplianceStatus),
		Metadata:         metadataJSONToMap(r.Metadata),
		Version:          r.Version,
		CreatedBy:        r.CreatedBy,
		UpdatedBy:        r.UpdatedBy,
		CreatedAt:        timeToTs(r.CreatedAt),
		UpdatedAt:        timeToTs(r.UpdatedAt),
	}

	if len(r.SupplyChainEvents) > 0 {
		proto.SupplyChainEvents = make([]*pb.SupplyChainEvent, 0, len(r.SupplyChainEvents))
		for i := range r.SupplyChainEvents {
			proto.SupplyChainEvents = append(proto.SupplyChainEvents, supplyChainEventToProto(&r.SupplyChainEvents[i]))
		}
	}

	if len(r.Certifications) > 0 {
		proto.Certifications = make([]*pb.Certification, 0, len(r.Certifications))
		for i := range r.Certifications {
			proto.Certifications = append(proto.Certifications, certToProto(&r.Certifications[i]))
		}
	}

	return proto
}

